#include <stdio.h>

static int is_whitespace(unsigned char b) {
    return b == ' ' || b == '\t' || b == '\n' ||
           b == '\v'   || b == '\f'  || b == '\r';
}

int main(void) {
    int ch;

    size_t lines = 0, words = 0, bytes = 0;
    size_t maxlen = 0, cur_line = 0;
    int in_word = 0;

    while ((ch = fgetc(stdin)) != EOF) {
        bytes++;

        if (ch == '\n') {
            lines++;
            if (cur_line > maxlen) maxlen = cur_line;
            cur_line = 0;
            in_word = 0;
        } else {
            cur_line++;
            if (!in_word && !is_whitespace((unsigned char)ch)) {
                words++;
                in_word = 1;
            }
        }
    }

    if (cur_line > maxlen) maxlen = cur_line;

    printf("%zu %zu %zu %zu\n", lines, words, bytes, maxlen);
    return 0;
}

