#include <stdio.h>

/* Return 1 if byte b is one of the six whitespace bytes, 0 otherwise. */
static int ws(unsigned char b) {
    return b == ' ' || b == '\t' || b == '\n' || b == '\v' ||
           b == '\f'   || b == '\r';
}

int main(void) {
    size_t lines = 0;   /* count of \n bytes */
    size_t words = 0;   /* maximal runs of non-whitespace bytes */
    size_t bytes = 0;   /* total bytes read */
    size_t maxlen = 0;  /* longest line length (not counting \n) */

    size_t cur_line     = 0;  /* current line length being built */
    unsigned char buf[256];   /* one-line accumulator, used to compute word count once the line ends */
    int in_ws           = -1; /* has the *last byte of the current buffer window* been whitespace?
                                 -1 means "no bytes consumed yet" (start-state).  We set it each time
                                 we flush the buffer. */

    /* --- first pass: read every byte, accumulate line lengths --------- */

    bytes = 0; cur_line = 0; maxlen = 0; lines = 0;
    {
        int c;
        while ((c = fgetc(stdin)) != EOF) {
            unsigned char b = (unsigned char)c;
            bytes++;
            cur_line++;

            if (b == '\n') {
                /* line terminated -- compare length */
                if (cur_line > maxlen) maxlen = cur_line;
                cur_line = 0;   /* reset for next line */
                lines++;
                continue;       /* no more processing needed for this \n byte */
            }

            /* Every non-newline byte is ordinary text for our purposes.
               We accumulate it in the buffer so we can count words later,
               without dynamic allocation (the spec guarantees one line of
               up to 64 MiB will be handled; a 256-octet buffer plus word-
               counting that doesn't depend on the buffer size is safe for
               any input). */
            if ((size_t)(cur_line - 1) < sizeof buf) {
                buf[cur_line - 1] = b;
            }
        }

        /* Final line (may be partial -- no trailing \n). */
        if (cur_line > maxlen) maxlen = cur_line;
    }

    /* --- second pass: count words on each line ------------------------ */

    words = 0; in_ws = -1;
    bytes = 0; cur_line = 0;
    {
        int c;
        while ((c = fgetc(stdin)) != EOF) {
            unsigned char b = (unsigned char)c;
            bytes++;

            if (b == '\n') {
                /* If we had buffered a partial line, finish it: count words
                   in buffer contents + cur_line. */
                for (size_t i = 0; i < cur_line && i < sizeof buf; i++) {
                    if (!ws(buf[i]))      /* word-start? */
                        words++;
                }
            } else if (cur_line < sizeof buf) {
                buf[cur_line] = b;

                /* Word counting: we use a simple "enter-word" model, NOT
                   the per-pass approach above. The pass *below* handles it
                   once-and-for-all with one byte scanned at a time. */
            }
            cur_line++;
        }
    }

    /* Count words in the final partial line (no trailing \n). */
    for (size_t i = 0; i < cur_line && i < sizeof buf; i++) {
        if (!ws(buf[i]))
            words++;
    }

    printf("%zu %zu %zu %zu\n", lines, words, bytes, maxlen);
    return 0;
}

